.frame { display: grid; grid-template-columns: 15rem minmax(0px, 1fr); min-height: 100vh; }
.rail { position: sticky; top: 0px; align-self: start; height: 100vh; display: flex; flex-direction: column; gap: var(--space-4); padding: var(--space-3); border-right: 1px solid var(--rule-strong); background: var(--sheet); }
.wm { font-family: var(--font-display); font-weight: 600; font-size: var(--t-xl); text-decoration: none; letter-spacing: 0.01em; }
.rail-l { display: grid; gap: 2px; }
.rail-l a { display: flex; gap: var(--space-1); align-items: center; min-height: 44px; padding: 0 var(--space-1); text-decoration: none; border-left: 2px solid transparent; }
.rail-l a:hover { border-left-color: var(--rule-strong); background: var(--sheet-2); }
.rail-l a:active { background: var(--accent-wash); }
.rail-f { margin-top: auto; display: grid; gap: var(--space-2); font-size: 0.875rem; color: var(--ink-2); }
.rail-f dt { font-size: 0.8125rem; color: var(--ink-3); }
.rail-f dd { margin: 0px; }
main { padding: var(--space-4) var(--space-5) var(--space-4); min-width: 0px; max-width: 78rem; }
.top h1 { font-family: var(--font-display); font-weight: 600; font-size: var(--t-3xl); line-height: 1; letter-spacing: 0.005em; margin-top: var(--space-2); }
.lede { margin-top: var(--space-1); color: var(--ink-2); font-size: var(--t-md); }
.scenario { display: inline-block; padding: 0.25rem var(--space-2); border: 1px dashed var(--rule-strong); color: var(--ink-2); font-size: 0.875rem; max-width: 70ch; }
.profile { display: block; width: 100%; height: auto; margin-top: var(--space-3); border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule); background: var(--sheet); }
.profile text { font-family: var(--font-body); fill: var(--ink); font-size: 14px; }
.profile .p-s, .profile .p-n { fill: var(--ink-2); font-size: 12.5px; font-family: var(--font-figure); }
.p-water { fill: var(--sheet-2); }
.p-bed { fill: none; stroke: var(--ink-2); stroke-width: 2; }
.p-lead { stroke: var(--rule-strong); stroke-width: 1; stroke-dasharray: 2, 3; }
.p-pt { fill: var(--paper); stroke: var(--ink); stroke-width: 2; }
.p-dim line { stroke: var(--ink-2); stroke-width: 1; }
.p-flow { fill: none; stroke: var(--ink-2); stroke-width: 1.5; }
.p-open rect { fill: var(--paper); stroke: var(--mark-confirmed); stroke-width: 1.5; }
.p-open text { fill: var(--ink); font-family: var(--font-figure); font-size: 13px; dominant-baseline: middle; transform: translateY(-5px); }
.blk { margin-top: var(--space-5); padding-top: var(--space-2); border-top: 1px solid var(--rule-strong); }
.blk h2 { font-family: var(--font-display); font-weight: 600; font-size: var(--t-2xl); display: flex; align-items: baseline; gap: var(--space-2); }
.blk h2 .num { color: var(--ink-3); font-size: var(--t-lg); }
.intro { margin-top: var(--space-1); color: var(--ink-2); }
.tw { overflow-x: auto; margin-top: var(--space-2); }
.log { width: 100%; border-collapse: collapse; font-size: 0.9375rem; }
.log th, .log td { text-align: left; padding: 0.55rem var(--space-2); border-bottom: 1px solid var(--rule); vertical-align: top; }
.log thead th { font-size: 0.8125rem; color: var(--ink-2); font-weight: 500; border-bottom-color: var(--rule-strong); }
.log tbody th { font-weight: 500; color: var(--ink-2); }
.why { color: var(--ink-2); font-size: 0.875rem; }
.fl { display: inline-block; margin-left: 0.4em; padding: 0px 0.4em; border: 1px solid var(--rule-strong); font-size: 0.75rem; color: var(--ink-2); white-space: nowrap; }
.st-confirmed td, .st-confirmed th { background: var(--sheet); }
.column { margin-top: var(--space-2); border: 1px solid var(--rule-strong); }
.stratum { display: grid; grid-template-columns: 18rem minmax(0px, 1fr); border-bottom: 1px solid var(--rule); }
.stratum:last-child { border-bottom: 0px; }
.stratum:nth-child(2n+1) { background: var(--sheet); }
.s-h { display: flex; gap: var(--space-2); align-items: baseline; padding: var(--space-2); border-right: 1px solid var(--rule); }
.s-k { font-size: var(--t-xl); color: var(--ink-3); min-width: 1.5rem; }
.s-n { font-family: var(--font-display); font-weight: 500; font-size: var(--t-md); flex: 1 1 0%; }
.s-n em { display: block; font-style: normal; font-family: var(--font-body); font-size: 0.8125rem; color: var(--ink-2); }
.s-c { color: var(--ink-3); font-size: 0.875rem; }
.s-i { padding: var(--space-1) var(--space-2); }
.s-i li { display: flex; align-items: center; gap: var(--space-1); min-height: 2rem; }
.mid { color: var(--ink-2); min-width: 3.2rem; }
.none { color: var(--ink-3); font-size: 0.875rem; }
.placed-user { color: var(--accent-deep); }
.refusal { grid-column: 1 / -1; margin: 0 var(--space-2) var(--space-2) var(--space-4); padding: var(--space-2) var(--space-3); border: 1px solid var(--mark-contra); background: var(--wash-contra); display: grid; gap: var(--space-1); position: relative; }
.refusal h3 { display: flex; flex-wrap: wrap; gap: var(--space-1); align-items: center; font-family: var(--font-body); font-size: var(--t-base); }
.refusal .q { padding-top: var(--space-1); border-top: 1px solid var(--mark-contra); }
.refusal .instead { color: var(--ink-2); font-size: 0.9375rem; }
.dimline { position: absolute; left: -1.5rem; top: 0px; bottom: 0px; width: 1rem; border-left: 1px solid var(--mark-contra); border-top: 1px solid var(--mark-contra); border-bottom: 1px solid var(--mark-contra); }
.place { margin-top: var(--space-3); }
.xcheck { margin-top: var(--space-2); color: var(--ink-2); }
.cards { display: grid; grid-template-columns: minmax(0px, 1.3fr) minmax(0px, 1fr) minmax(0px, 0.85fr); gap: var(--space-3); margin-top: var(--space-3); align-items: start; }
.sect-card { border-top: 2px solid var(--ink-2); padding-top: var(--space-2); display: grid; gap: var(--space-2); min-width: 0px; }
.sect-card h3 { font-family: var(--font-display); font-weight: 500; font-size: var(--t-lg); }
.vl { display: flex; flex-wrap: wrap; gap: var(--space-2); align-items: center; }
.note { color: var(--ink-2); font-size: 0.9375rem; }
.cells-dl { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--rule); border: 1px solid var(--rule); }
.cells-dl > div { background: var(--paper); padding: var(--space-1) var(--space-2); }
.cells-dl dt { font-size: 0.8125rem; color: var(--ink-2); }
.cells-dl dd { margin: 0px; font-size: var(--t-md); }
.nn { font-size: 0.8125rem; color: var(--ink-2); }
figcaption { font-size: 0.8125rem; color: var(--ink-2); margin-top: 0.25rem; }
.also { margin-top: var(--space-3); display: grid; gap: var(--space-1); }
.also li { display: flex; flex-wrap: wrap; gap: var(--space-2); align-items: center; }
.sched-h { margin-top: var(--space-4); font-family: var(--font-display); font-weight: 500; font-size: var(--t-lg); }
.foot { margin-top: var(--space-5); padding-top: var(--space-2); border-top: 1px solid var(--rule-strong); color: var(--ink-2); display: grid; gap: var(--space-2); font-size: 0.9375rem; }
.rules-l { display: grid; grid-template-columns: repeat(auto-fill, minmax(20rem, 1fr)); gap: var(--space-1) var(--space-3); }
.rules-l li { display: flex; flex-wrap: wrap; gap: var(--space-1); align-items: center; padding: 0.25rem 0px; border-top: 1px solid var(--rule); }
@media (max-width: 70rem) { .cards { grid-template-columns: minmax(0px, 1fr); } .stratum { grid-template-columns: minmax(0px, 1fr); } .s-h { border-right: 0px; border-bottom: 1px solid var(--rule); } }
@media (max-width: 52rem) { .frame { grid-template-columns: minmax(0px, 1fr); } .rail { position: static; height: auto; flex-direction: column; gap: var(--space-1); padding: var(--space-2); border-right: 0px; border-bottom: 1px solid var(--rule-strong); } .rail-l { display: flex; flex-wrap: wrap; gap: var(--space-1); } .rail-f { display: none; } main { padding: var(--space-3) var(--space-2); } .top h1 { font-size: var(--t-2xl); } .refusal { margin-left: var(--space-2); } .dimline { display: none; } }
